class Solution {
    public int arithmeticTriplets(int[] nums,int diff){
        Set<Integer> values=new HashSet<>();
        for(int value:nums)values.add(value);
        int answer=0;
        for(int value:nums)if(values.contains(value+diff)&&values.contains(value+2*diff))answer++;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun arithmeticTriplets(nums:IntArray,diff:Int):Int{
        val values=nums.toHashSet();
        var answer=0;
        for(value in nums)if(value+diff in values&&value+2*diff in values)answer++;
        return answer
    }
}

code.cpp:
class Solution {
    public:int arithmeticTriplets(vector<int>& nums,int diff){
        unordered_set<int> values(nums.begin(),nums.end());
        int answer=0;
        for(int value:nums)if(values.count(value+diff)&&values.count(value+2*diff))++answer;
        return answer;
    }
};
